<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><section class="workspace"><div class="container"><div class="page-heading"><div><p class="eyebrow">Team access</p><h1>Users</h1><p>Manage staff identities and operational roles.</p></div><a class="btn btn-accent" href="<?= site_url('users/new') ?>">Add user</a></div><?php if(!$users): ?><div class="empty-state"><h2>No users found</h2><p>Create a staff account to get started.</p></div><?php else: ?><div class="table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th scope="col">User</th><th scope="col">Full name</th><th scope="col">Role</th><th scope="col">Created</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><div class="d-flex align-items-center gap-3"><img class="avatar" src="<?= $user['avatar']?base_url('uploads/avatars/'.rawurlencode($user['avatar'])):base_url('assets/avatar-placeholder.svg') ?>" alt=""><span class="fw-semibold"><?= esc($user['username']) ?></span></div></td><td><?= esc($user['full_name']) ?></td><td><span class="role-badge"><?= esc(ucfirst($user['role'])) ?></span></td><td><?= esc(date('M j, Y',strtotime($user['created_at']))) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('users/'.$user['id'].'/edit') ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?></div></section><?= $this->endSection() ?>
